package com.ianblk.zianmobs;
import java.util.*;
public final class NpcProfiles {
 public record Skin(String id,String name,boolean slim){}
 public static final List<Skin> SKINS=List.of(new Skin("abyss_guard","Guardián abisal",false),new Skin("eclipse_sentinel","Centinela del eclipse",false),new Skin("glacial_duelist","Espadachín glacial",false),new Skin("solar_knight","Caballero solar",false),new Skin("frost_specter","Espectro de escarcha",false),new Skin("emerald_guard","Guardián esmeralda",false),new Skin("obsidian_knight","Caballero de obsidiana",false),new Skin("alaric_zafiro","Alaric del Zafiro",true),new Skin("soren_hielo","Soren del Hielo",true),new Skin("nyx_umbral","Nyx del Umbral",true),new Skin("iris_prismatica","Iris Prismática",false),new Skin("kael_invierno","Kael del Invierno",true),new Skin("elian_alba","Elian del Alba",true),new Skin("darian_roble","Darian del Roble",false),new Skin("varek_carmesi","Varek Carmesí",false),new Skin("liora_arena","Liora de Arena",false),new Skin("vigia_sculk","Vigía del Sculk",false),new Skin("morgana_cosecha","Morgana de la Cosecha",false),new Skin("heraldo_vacio","Heraldo del Vacío",false),new Skin("arlequin_estelar","Arlequín Estelar",true),new Skin("sombra_violeta","Sombra Violeta",true),new Skin("centinela_carmesi","Centinela Carmesí",true),new Skin("nadir_medianoche","Nadir de Medianoche",true),new Skin("guardia_cobalto","Guardia de Cobalto",true),new Skin("serafina_nieves","Serafina de las Nieves",true),new Skin("lucien_ocaso","Lucien del Ocaso",false),new Skin("mika_rosada","Mika Rosada",true),new Skin("espectro_sculk","Espectro del Sculk",false),new Skin("ignis_brasero","Ignis del Brasero",true),new Skin("noir_eclipse","Noir del Eclipse",true),new Skin("silas_obsidiana","Silas de Obsidiana",true),new Skin("amelia_flores","Amelia de las Flores",true),new Skin("sol_ambar","Sol del Ámbar",true),new Skin("magnus_cobre","Magnus de Cobre",true));
 public record Spec(String skin,boolean slim,boolean hostile,int attackCooldown,int skillCooldown,double range,double skillDamage,boolean sonic,boolean dragon,boolean wither,boolean blaze){
  public Spec{if(SKINS.stream().noneMatch(s->s.id().equals(skin))||attackCooldown<20||attackCooldown>400||skillCooldown<40||skillCooldown>2400||!Double.isFinite(range+skillDamage)||range<4||range>32||skillDamage<0||skillDamage>64)throw new IllegalArgumentException("NPC: skin válida; golpe 20–400 ticks; habilidad 40–2400 ticks; alcance 4–32; daño especial 0–64");}
  public List<String> skills(){var result=new ArrayList<String>();if(sonic)result.add("SONIC");if(dragon)result.add("DRAGON");if(wither)result.add("WITHER");if(blaze)result.add("BLAZE");return result;}
 }
 public static Spec defaults(String template){String skin=template.startsWith("npc_")?template.substring(4):"abyss_guard";if(!SKINS.stream().map(Skin::id).toList().contains(skin))skin="abyss_guard";final String chosen=skin;return new Spec(skin,SKINS.stream().filter(s->s.id().equals(chosen)).findFirst().orElseThrow().slim(),true,30,160,20,6,false,false,false,false);}
 private NpcProfiles(){}
}
